"""Luhn check for card numbers."""

_DIGITS = set("0123456789")


def valid(number):
    if not isinstance(number, str):
        return False
    groups = number.split(" ")
    if any(not g or set(g) - _DIGITS for g in groups):
        return False
    digits = "".join(groups)
    if len(digits) < 2:
        return False
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = ord(ch) - 48
        if i % 2:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0
